fn rolling_max(s: &Vec<i8>) -> Option<i8> {
    if s.len() < 2 {
        return None;
    }

    // Initialize first and second using the first two elements.
    let (mut first, mut second) = if s[0] >= s[1] {
        (s[0], s[1])
    } else {
        (s[1], s[0])
    };

    // Process the rest of the array.
    for &v in s.iter().skip(2) {
        if v > first {
            // New maximum found.
            second = first;
            first = v;
        } else if v > second {
            // Better “second place” found.
            second = v;
        }
    }

    Some(second)
}

